const input = $input.first().json;
const rawUrl = (input.youtube_url || input['YouTube URL'] || '').trim();
const rawCount = input.short_count || input['How many Shorts do you want to create?'] || 2;
const templateName = input.template_name || 'Hormozi 2';
const privacyStatus = input.privacy_status || 'private';

if (!rawUrl) {
  throw new Error('YouTube URL is required.');
}

const ytRegex = /(?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/(?:watch\?v=|shorts\/)|youtu\.be\/)([a-zA-Z0-9_-]{11})/;
const match = rawUrl.match(ytRegex);
if (!match) {
  throw new Error('Invalid YouTube URL: ' + rawUrl + '. Please provide a valid youtube.com or youtu.be link.');
}
const videoId = match[1];
const cleanUrl = 'https://www.youtube.com/watch?v=' + videoId;

const shortCount = parseInt(rawCount, 10);
if (isNaN(shortCount) || shortCount <= 0) {
  throw new Error('Short count must be a positive integer greater than 0.');
}
if (shortCount > 10) {
  throw new Error('Maximum configurable Shorts per execution is 10.');
}

return [{
  json: {
    youtube_url: cleanUrl,
    source_video_id: videoId,
    short_count: shortCount,
    template_name: templateName,
    privacy_status: privacyStatus,
    timestamp: new Date().toISOString()
  }
}];

const data = $input.first().json;
const initial = $('Validate Inputs').first().json;
const clips = data.clips || [];

if (clips.length === 0) {
  throw new Error('No suitable clips could be created from the source video.');
}

return clips.map(clip => ({
  json: {
    ...clip,
    source_video_id: data.video_id,
    source_url: initial.youtube_url,
    total_requested: data.total_requested,
    total_created: data.total_created,
    template_name: initial.template_name,
    privacy_status: initial.privacy_status
  }
}));

const staticData = $getWorkflowStaticData('global');
const results = staticData.processedShorts || [];

// Reset static data for next execution
staticData.processedShorts = [];

const initialInput = $('Validate Inputs').first().json;
const requested = initialInput.short_count;
const created = results.length;

let successYt = 0;
let successIg = 0;

let lines = [
  '═══════════════════════════════════════════════',
  '🎬 SHORTS & REELS AUTOMATION SUMMARY',
  '═══════════════════════════════════════════════',
  'Source YouTube Video: ' + initialInput.youtube_url,
  'Shorts Requested: ' + requested,
  'Shorts Created: ' + created,
  ''
];

results.forEach(r => {
  if (r.youtube_status === 'success') successYt++;
  if (r.instagram_status === 'success') successIg++;

  lines.push('───────────────────────────────────────────────');
  lines.push('📌 SHORT ' + r.clip_index + ': ' + r.clip_title);
  lines.push('   Virality Score: ' + Math.round(r.virality_score) + '/100 | Duration: ' + Math.round(r.duration) + 's');
  lines.push('   YouTube: ' + (r.youtube_url ? r.youtube_url : '✗ (' + (r.youtube_error || 'OAuth pending') + ')'));
  lines.push('   Instagram: ' + (r.instagram_permalink ? r.instagram_permalink : '✗ (' + (r.instagram_error || 'OAuth pending') + ')'));
  lines.push('   Direct Video: ' + r.direct_url);
});

lines.push('───────────────────────────────────────────────');
lines.push('');
lines.push('Platform Upload Totals:');
lines.push('YouTube Uploads: ' + successYt + '/' + created);
lines.push('Instagram Reels: ' + successIg + '/' + created);

if (successYt < created) {
  lines.push('');
  lines.push('ℹ️ Note: To enable live YouTube uploads, authorize the YouTube OAuth2 credential in n8n.');
}
if (successIg < created) {
  lines.push('ℹ️ Note: To enable live Instagram publishing, configure your Meta/Instagram Graph API token.');
}

const summaryText = lines.join('\n');

return [{
  json: {
    summary: summaryText,
    total_requested: requested,
    total_created: created,
    successful_youtube: successYt,
    successful_instagram: successIg,
    results: results
  }
}];

const item = $input.first().json;

const hashStr = item.source_video_id + '_' + Math.round(item.start_time * 10) + '_' + Math.round(item.end_time * 10);
let hashVal = 0;
for (let i = 0; i < hashStr.length; i++) {
  hashVal = ((hashVal << 5) - hashVal) + hashStr.charCodeAt(i);
  hashVal |= 0;
}
const clipHash = (item.source_video_id + '_' + Math.abs(hashVal).toString(16)).slice(0, 32);

const titleClean = (item.title || 'Viral Short Highlight').replace(/["']/g, '').replace(/\r?\n/g, ' ').trim();
const snippet = (item.transcript_snippet || item.lyrics || '').replace(/\r?\n/g, ' ').trim();

let ytTitle = titleClean;
if (ytTitle.length > 55) {
  ytTitle = ytTitle.slice(0, 52) + '...';
}
ytTitle = ytTitle + ' #Shorts';

const ytDesc = titleClean + '\n\n' + (snippet ? snippet : 'Watch until the end!') + '\n\nSource: ' + item.source_url + '\nLanguage: ' + (item.language_name || item.language || 'Original') + '\nVirality Score: ' + Math.round(item.virality_score) + '/100\n\n#shorts #viral #reels #trending';

const ytTags = 'shorts,viral,reels,trending,shortsfeed';

const igCaption = '⚡ ' + titleClean + '\n\n' + (snippet ? snippet : 'Save this for later!') + '\n\n👉 Follow for more high-value clips!\n\n#reels #reelsinstagram #viralreels #shorts';

return [{
  json: {
    ...item,
    clip_hash: clipHash,
    yt_title: ytTitle,
    yt_description: ytDesc,
    yt_tags: ytTags,
    ig_caption: igCaption
  }
}];

const ytResult = $input.first().json;
const clipData = $('Generate Metadata & Check Duplicates').first().json;

let ytVideoId = null;
let ytUrl = null;
let ytStatus = 'failed';
let ytError = null;

if (ytResult.id) {
  ytVideoId = ytResult.id;
  ytUrl = 'https://www.youtube.com/shorts/' + ytVideoId;
  ytStatus = 'success';
} else if (ytResult.error) {
  ytError = ytResult.error.message || JSON.stringify(ytResult.error);
} else {
  ytError = 'YouTube OAuth2 authorization required in n8n credentials';
}

return [{
  json: {
    ...clipData,
    youtube_video_id: ytVideoId,
    youtube_url: ytUrl,
    youtube_status: ytStatus,
    youtube_error: ytError
  }
}];

const igResult = $input.first().json;
const current = $('Process YouTube Result').first().json;

let igMediaId = null;
let igPermalink = null;
let igStatus = 'failed';
let igError = null;

if (igResult.id) {
  igMediaId = igResult.id;
  igPermalink = igResult.permalink || ('https://www.instagram.com/reel/' + igMediaId);
  igStatus = 'success';
} else if (igResult.error) {
  igError = igResult.error.message || JSON.stringify(igResult.error);
} else {
  igError = 'Meta/Instagram OAuth authorization required';
}

return [{
  json: {
    ...current,
    instagram_media_id: igMediaId,
    instagram_permalink: igPermalink,
    instagram_status: igStatus,
    instagram_error: igError,
    processed_at: new Date().toISOString()
  }
}];

const item = $input.first().json;

const staticData = $getWorkflowStaticData('global');
if (!staticData.processedShorts) {
  staticData.processedShorts = [];
}

staticData.processedShorts.push({
  clip_index: item.clip_index,
  clip_title: item.title || item.yt_title,
  duration: item.duration,
  virality_score: item.virality_score,
  youtube_url: item.youtube_url,
  youtube_status: item.youtube_status,
  youtube_error: item.youtube_error,
  instagram_permalink: item.instagram_permalink,
  instagram_status: item.instagram_status,
  instagram_error: item.instagram_error,
  direct_url: item.direct_url,
  clip_hash: item.clip_hash
});

return [{ json: item }];

